/**
 * Bridge between the IdP callback and `workers-oauth-provider`.
 *
 * When an MCP client kicks off OAuth, the user lands on the IdP via
 * /idp/{idp}/start?oauth_request_id=<id>. After the IdP callback
 * verifies + upserts the user, this helper consumes the original
 * authorize request from KV and calls `provider.completeAuthorization`
 * — that returns the redirect URL with the OAuth code that the MCP
 * client trades for an access token at /oauth/token.
 *
 * `props` is the small set of claims we want attached to every
 * authenticated MCP request (userId, email, role). The provider
 * encrypts and stores it on the token; McpAgent reads it via
 * `ctx.props` per request.
 */

import { clearStateCookie } from './common'
import { consumeAuthRequest } from '../oauth/authorize-page'
import type { Env, McpProps } from '../env'
import type { UserRow } from '../db/queries/users'

export async function completeMcpAuthorization(
  env: Env,
  oauthRequestId: string,
  user: UserRow
): Promise<Response> {
  const authReq = await consumeAuthRequest(env, oauthRequestId)
  if (!authReq) {
    // The KV entry expired or was double-consumed. Bounce back to
    // sign-in with a friendly error — the MCP client will see the
    // failure surfaced as a missing token and prompt re-authorize.
    // Clear the IdP state cookie too so the user starts cleanly on
    // the retry; the success path already clears it below.
    const url = new URL('/sign-in', env.PUBLIC_BASE_URL)
  env: Env,
  helpers: OAuthHelpers
): Promise<UserGrantIndex> {
  const { grants, complete } = await listAllGrants(env, helpers)
  const index = new Map<string, OAuthClientUserRef[]>()
  for (const g of grants) {
    const list = index.get(g.clientId) ?? []
    const existing = list.find((ref) => ref.userId === g.userId)
    if (existing) {
      if (g.createdAt < existing.grantedAt) existing.grantedAt = g.createdAt
    } else {
      list.push({
        userId: g.userId,
        email: g.user.email,
        name: g.user.name,
        grantedAt: g.createdAt
      })
    }
    index.set(g.clientId, list)
  }
  // Stable ordering per client — earliest grant first.
  for (const list of index.values()) list.sort((a, b) => a.grantedAt - b.grantedAt)
  return { index, complete }
}
  if (client.tokenEndpointAuthMethod !== 'none') return false // confidential
  if (grantIndex.has(client.clientId)) return false // has grants
  // No registrationDate ⇒ can't age it ⇒ keep (don't delete blind).
  if (typeof client.registrationDate !== 'number') return false
  return client.registrationDate < cutoffSeconds
}

/**
 * Core loop, decoupled from the grant-index build so it's unit-testable
 * with a mock helpers + a plain Map. Paginates all clients and deletes
 * the prunable ones best-effort.
 */
export async function pruneClientsByPolicy(
  helpers: Pick<OAuthHelpers, 'listClients' | 'deleteClient'>,
  grantIndex: ReadonlyMap<string, unknown>,
  cutoffSeconds: number
): Promise<Omit<PruneClientsResult, 'skippedIncompleteIndex'>> {
  let scanned = 0
  let orphans = 0
  let deleted = 0
  let failed = 0
  const deletedIds: string[] = []

  let cursor: string | undefined
  let pages = 0
  do {
    const page = await helpers.listClients({ limit: 200, cursor })
    for (const client of page.items) {
      scanned++
      if (!isPrunableClient(client, grantIndex, cutoffSeconds)) continue
      orphans++
      try {
        await helpers.deleteClient(client.clientId)
        deleted++
        deletedIds.push(client.clientId)
      } catch (err) {
        failed++
        console.warn(
          `[prune-clients] deleteClient(${client.clientId}) failed:`,
          errMessage(err)
        )
      }
    }
    cursor = page.cursor
    // Safety backstop against an ill-behaved cursor — 50×200 = 10k
    // clients, far beyond any realistic registration count.
    if (++pages > 50) {
      console.warn('[prune-clients] stopped after 50 pages; cursor may be looping')
      break
    }
  } while (cursor)

