144:  it('happy path: PKCE S256 flow issues a usable access token (harness guard)', async () => {
156:  it('authorization codes are single-use: replay is rejected', async () => {
168:  it('PKCE: a wrong verifier is rejected', async () => {
179:  it('PKCE: omitting the verifier at token time is rejected', async () => {
188:  it('PKCE: a public client cannot run the code flow without PKCE at all', async () => {
203:  it('redirect_uri: an unregistered redirect_uri never receives a code', async () => {
215:  it('redirect_uri: token exchange with a mismatched redirect_uri is rejected', async () => {
241:  it('a new login carries no absolute expiry', async () => {
255:  it('neither the grant nor the client record is written with a KV expiration', async () => {
279:  it('every token exchange stamps the login-activity ledger, once per grant', async () => {
327:  it('the idle window is a policy constant, not a library default', () => {
331:  it('access tokens last 7 days on both the code exchange and a refresh', async () => {
377:  it('advertises `<mcp base>/mcp` as the protected resource', async () => {
385:  it('the 401 on /mcp points clients at that resource metadata', async () => {
393:  it('refuses an authorization request that names a different resource', async () => {
401:  it('no longer serves the legacy /sse endpoint as a protected API route', async () => {
    body: JSON.stringify({
      client_name: 'sec-test-client',
      redirect_uris: [REDIRECT],
      token_endpoint_auth_method: 'none',
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code']
    })
  })
  expect(res.status).toBe(201)
  const body = (await res.json()) as { client_id: string }
  return body.client_id
}

function b64url(buf: ArrayBuffer): string {
  return btoa(String.fromCharCode(...new Uint8Array(buf)))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '')
}

async function s256(verifier: string): Promise<string> {
  return b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier)))
}

function authorizeUrl(
  clientId: string,
  opts: { challenge?: string; redirectUri?: string } = {}
): string {
  const url = new URL(`${BASE}/oauth/authorize`)
  url.searchParams.set('client_id', clientId)
  url.searchParams.set('redirect_uri', opts.redirectUri ?? REDIRECT)
  url.searchParams.set('response_type', 'code')
  url.searchParams.set('scope', 'mcp')
  url.searchParams.set('state', 'st-1')
  if (opts.challenge) {
    url.searchParams.set('code_challenge', opts.challenge)
    url.searchParams.set('code_challenge_method', 'S256')
  }
  return url.toString()
}

/**
 * Run the server-side authorize leg the way production does: parse the
 * authorize request, then complete it for a signed-in user. Returns the
 * `code` the client would receive on its redirect_uri.
 */
async function issueCode(
  clientId: string,
  opts: { challenge?: string; redirectUri?: string } = {}
): Promise<string> {
  const helpers = getOAuthApi<WorkerEnv>(oauthProviderOptions(testEnv), testEnv)
  const authReq = await helpers.parseAuthRequest(new Request(authorizeUrl(clientId, opts)))
  const { redirectTo } = await helpers.completeAuthorization({
    request: authReq,
    userId: 'u-sec',
    metadata: { idp: 'github', email: 'sec@test.example' },
    scope: ['mcp'],
    props: { userId: 'u-sec', email: 'sec@test.example', role: 'member' }
  })
  const code = new URL(redirectTo).searchParams.get('code')
  if (!code) throw new Error(`no code on redirect: ${redirectTo}`)
  return code
}

async function exchange(
  clientId: string,
  code: string,
  opts: { verifier?: string; redirectUri?: string } = {}
): Promise<Response> {
